/**
 * Test runner for `match_baton_profile.groovy`
 *
 * Executes the fixture tests listed below,
 * comparing the lookup key and match result generated by `buildLookupResult`
 * against the expected results. The `buildLookupResult` closure, which coordinates
 * all the business logic for building the Baton lookup key,
 * is loaded from `match_baton_profile.groovy` by way of a Groovy Binding.
 */

def tests = [
    [
        fixture: 'fixtures/test_mxf_package_mxf-atom_wrapper.xml',
        expectedLookupKey:
            'MAMs_MXF_2048x1080_JPEG2000_24fps_1.9_12bit_PCM_48.24_6.0',
        expectedMatchResult: 'Match'
    ], // tests MXF package with wrapper MXF-ATOM
    [
        fixture: 'fixtures/test_mxf_package_mxf_wrapper.xml',
        expectedLookupKey:
            'MAMs_MXF_4096x2160_JPEG2000_24fps_1.9_12bit_PCM_48.24_6.0',
        expectedMatchResult: 'Match'
    ], // tests MXF package with wrapper MXF
    [
        fixture: 'fixtures/test_audio_only.xml',
        expectedLookupKey: 'MAMs_WAV_PCM_48.24_1.0',
        expectedMatchResult: 'Match'
    ], // tests audio-only XML input
    [
        fixture: 'fixtures/test_codec_BGR24_to_rgb.xml',
        expectedLookupKey: 'MAMs_AVI_1440x1080_RGB_25fps_4.3_8bit_MOS',
        expectedMatchResult: 'Match'
    ], // tests BGR24 to RGB codec mapping
    [
        fixture: 'fixtures/test_codec_prores_4444_to_4444.xml',
        expectedLookupKey:
            'MAMs_QT_1920x1080_4444_24fps_16.9_12bit_PCM_48.24_2.0',
        expectedMatchResult: 'Match'
    ], // tests PRORES_4444 to 4444 mapping (also covers MPEG-4 to QT mapping for .mov)
    [
        fixture: 'fixtures/test_aspect_ratio_146:77_to_1.89.xml',
        expectedLookupKey:
            'MAMs_QT_4096x2160_422HQ_24fps_1.89_10bit_PCM_48.24_2.0',
        expectedMatchResult: 'Match'
    ], // tests aspect ratio mapping 146:77 to 1.89
    [
        fixture: 'fixtures/test_aspect_ratio_131:95_to_1.379.xml',
        expectedLookupKey:
            'MAMs_QT_2048x1485_422HQ_24fps_1.379_10bit_PCM_48.24_2.0',
        expectedMatchResult: 'Match'
    ], // tests aspect ratio mapping 131:95 to 1.379
    [
        fixture: 'fixtures/test_bit_depth_8bit_for_dv.xml',
        expectedLookupKey:
            'MAMs_QT_720x480_DV_2997fps_4.3_8bit_PCM_48.16_1.0',
        expectedMatchResult: 'Match'
    ], // tests 8-bit depth mapping for DV
    [
        fixture: 'fixtures/test_bit_depth_8bit_for_dvcpro.xml',
        expectedLookupKey:
            'MAMs_AVI_720x480_DV_2997fps_4.3_8bit_PCM_48.16_2.0',
        expectedMatchResult: 'Match'
    ], // tests 8-bit depth mapping for DVCPro
    [
        fixture: 'fixtures/test_no_match.xml',
        expectedLookupKey: '',
        expectedMatchResult: 'No Match'
    ] // tests no match scenario using incomplete technical XML
]

/**
 * Groovy provides the `Binding` class as a way of sharing variables
 * between scripts. In this case, we use it to create
 * the `TEST_MODE` variable in the execution context, which signals to `match_baton_profile.groovy`,
 * when loaded via `GroovyShell.execute()`,
 * that it should just return the `buildLookupResult` closure for testing purposes,
 * rather than running the production code. This allows for isolated testing of the lookup key generation logic.
 */
def buildLookupResultBinding = new Binding([TEST_MODE: true])
def buildLookupResult = new GroovyShell(
    this.class.classLoader,
    buildLookupResultBinding
).evaluate(new File('match_baton_profile.groovy'))

def failedTests = []
def recordFailure = { test, message ->
    println "FAIL: ${test.fixture} (${message})"
    failedTests << test.fixture
}

tests.each { test ->
    def fixture = new File(test.fixture)

    if (!fixture.isFile()) {
        println "FAIL: ${test.fixture} (fixture not found)"
        failedTests << test.fixture
        return
    }

    try {
        def technicalXml = new groovy.xml.XmlSlurper(false, false).parse(fixture)
        def result = buildLookupResult(technicalXml)

        if (
            result.lookupKey == test.expectedLookupKey &&
            result.matchResult == test.expectedMatchResult
        ) {
            println "PASS: ${test.fixture}"
        } else {
            println "FAIL: ${test.fixture}"
            println "  expected key:    ${test.expectedLookupKey}"
            println "  actual key:      ${result.lookupKey}"
            println "  expected result: ${test.expectedMatchResult}"
            println "  actual result:   ${result.matchResult}"
            failedTests << test.fixture
        }
    } catch (java.io.IOException e) {
        recordFailure(test, e.message)
    } catch (org.xml.sax.SAXException e) {
        recordFailure(test, e.message)
    } catch (NumberFormatException e) {
        recordFailure(test, e.message)
    }
}

if (!failedTests.isEmpty()) {
    println 'Fixture tests failed: ' + failedTests.join(', ')
}
